package dev.smpcristalix.pvpcombat.listener;import dev.smpcristalix.pvpcombat.PvPCombatPlugin;import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import dev.smpcristalix.pvpcombat.service.*;import org.bukkit.Material;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.entity.PlayerDeathEvent;import org.bukkit.inventory.ItemStack;import org.bukkit.persistence.PersistentDataType;/** Death penalty, PvP reward and trophy totems in one death pipeline. */public final class DeathListener implements Listener{private final CombatService combat;private final PearlService pearls;private final DeathPenaltyService penalties;private final RewardService rewards;private PvPCombatSettings settings;public DeathListener(CombatService c,PearlService p,DeathPenaltyService d,RewardService r,PvPCombatSettings s){combat=c;pearls=p;penalties=d;rewards=r;settings=s;}public void reload(PvPCombatSettings s){settings=s;}@EventHandler(priority=EventPriority.HIGH)public void onDeath(PlayerDeathEvent e){Player v=e.getEntity();forceDrop(e);String lost=penalties.apply(v);if(lost!=null)v.sendMessage("§cПосле смерти потеряна ступень: §f"+lost);Player k=v.getKiller();if(k!=null&&!k.equals(v)){if(rewards.reward(k,v))k.sendMessage("§dТы получил Осколок за PvP-убийство.");markTotems(e,k,v);}combat.clear(v);pearls.reset(v);}private void forceDrop(PlayerDeathEvent e){if(!e.getKeepInventory())return;e.getDrops().clear();for(ItemStack i:e.getEntity().getInventory().getContents())if(i!=null&&!i.getType().isAir())e.getDrops().add(i.clone());e.setKeepInventory(false);e.getEntity().getInventory().clear();}private void markTotems(PlayerDeathEvent e,Player k,Player v){if(combat.fightDurationMillis(v)<settings.totemLootMinFightSeconds()*1000L)return;for(ItemStack d:e.getDrops()){if(d.getType()!=Material.TOTEM_OF_UNDYING)continue;var m=d.getItemMeta();m.getPersistentDataContainer().set(PvPCombatPlugin.TROPHY_TOTEM_KEY,PersistentDataType.STRING,k.getUniqueId().toString());d.setItemMeta(m);}}}
